<?php
namespace App\Models;
use App\Models\Concerns\InvalidatesPublicChrome;
use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Model;
class NavigationItem extends Model { use InvalidatesPublicChrome; protected $fillable=['navigation_menu_id','parent_id','label','link_type','route_name','page_id','solution_id','product_id','industry_id','capability_id','work_process_id','client_id','url','target','icon','description','badge_text','display_order','depth','is_active','is_featured','opens_mega_menu']; protected function casts():array{return ['is_active'=>'boolean','is_featured'=>'boolean','opens_mega_menu'=>'boolean'];} public function menu():BelongsTo{return $this->belongsTo(NavigationMenu::class,'navigation_menu_id');} public function parent():BelongsTo{return $this->belongsTo(self::class,'parent_id');} public function page():BelongsTo{return $this->belongsTo(Page::class);} public function solution():BelongsTo{return $this->belongsTo(Solution::class);} public function product():BelongsTo{return $this->belongsTo(Product::class);} public function industry():BelongsTo{return $this->belongsTo(Industry::class);} public function capability():BelongsTo{return $this->belongsTo(Capability::class);} public function workProcess():BelongsTo{return $this->belongsTo(WorkProcess::class);} public function client():BelongsTo{return $this->belongsTo(Client::class);} public function children():HasMany{return $this->hasMany(self::class,'parent_id')->orderBy('display_order')->orderBy('id');} }
